REPO_PATTERN = re.compile(r"[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]{1,100}")
REF_PATTERN = re.compile(r"[A-Za-z0-9][A-Za-z0-9_./-]{0,150}")
